import React from 'react'

/**
 * The Coco Club — official brand marks.
 *
 * These paths are traced from the studio's own brand guide (Varios/BrandQuickGuide.jpeg and
 * TheCocoClub.jpeg), so the groovy script wordmark and the twin-swirl heart are the REAL marks,
 * not a typographic stand-in. Every mark paints with `currentColor`: set the colour with a text
 * utility (e.g. `text-jacobean`, `text-lace`) on the element itself.
 *
 * Aspect ratios — size with height and let width follow, or vice versa:
 *   Wordmark         1000 x 560   (16:9-ish, lockup reads "THE coco club")
 *   WordmarkStacked   844 x 1000  (portrait lockup)
 *   Logomark         1000 x 848   (the heart, for favicons, avatars, small spaces)
 *   BrandRibbons     1200 x 211   (decorative liquid-swirl band)
 */
interface MarkProps {
  className?: string
  /** Give a title only when the mark is the sole carrier of meaning (e.g. a bare logo link). */
  title?: string
}

